ee:message.ee:set-payload:
%dw 2.0
output application/json
var req = vars.chatPayload default {}
var userMsgs = req.messages default []
var devPrompt = p("agent.general.developer_prompt")
---
if (sizeOf(userMsgs) > 0)
  { messages: userMsgs }
else
  {
    messages: [
      { role: "developer", content: devPrompt },
      { role: "user", content: req.message default "" }
    ]
  }

%dw 2.0
output application/json
import substring, trim from dw::core::Strings
---
do {
  var sec = ((p("agent.general.request_timeout_ms") as Number default 60000) / 1000) as String
  var tech = trim((error.detailedDescription default error.description default "") as String)
  var shortTech = if (sizeOf(tech) > 1800) substring(tech, 0, 1800) ++ "…" else tech
  var httpSt = (error.errorMessage.attributes.statusCode default null)
---
{
  reply: "The assistant did not respond within " ++ sec ++ " seconds. Please try again with a shorter question.",
  error: true,
  errorType: "TIMEOUT",
  debug: {
    muleErrorType: (error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default ""),
    statusCode: httpSt,
    detail: shortTech
  }
}
}

