%dw 2.0
output application/json
---
{
  reply: "Chat is not configured. Set agent.general.url, client_id, and client_secret in application properties.",
  error: true,
  errorType: "CONFIG",
  debug: {
    errorType: "CONFIG",
    detail: "Missing agent.general.url, client_id, or client_secret in application properties."
  }
}

%dw 2.0
output application/json
var req = vars.chatPayload default {}
var msgs = req.messages default []
var userMsgs = msgs filter (lower($.role default "") == "user")
var text = if (sizeOf(userMsgs) > 0)
  (userMsgs[-1].content default "")
else if (sizeOf(msgs) > 0)
  (msgs[-1].content default "")
else
  (req.message default "")
var mid = java!java::util::UUID::randomUUID() as String
var rid = java!java::util::UUID::randomUUID() as String
---
{
  jsonrpc: "2.0",
  id: rid as String,
  method: "message/send",
  params: {
    message: {
      kind: "message",
      messageId: mid as String,
      role: "user",
      parts: [{ kind: "text", text: text }]
    }
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
import * from dw::core::Strings
fun ensureTrailingSlash(s) = do {
  var z = trim(s default "")
  ---
  if (isEmpty(z)) z
  else if (endsWith(z, "/")) z
  else z ++ "/"
}
var br = vars.resolvedBroker
var stored = trim(br.chatUrl default "")
var cardU = trim((br.card default {}).url default "")
var b = trim(br.baseUrl default "")
---
ensureTrailingSlash(
  if (!isEmpty(stored)) stored
  else if (!isEmpty(cardU) and (startsWith(lower(cardU), "http://") or startsWith(lower(cardU), "https://"))) cardU
  else b
)

ee:message.ee:set-payload:
%dw 2.0
output application/json
import trim, isEmpty, substring from dw::core::Strings
/** Collect text from each part: .text, .content, or .body (A2A varies by producer). */
fun partText(p) =
  if (p == null) ""
  else if (p.text != null) trim(p.text as String default "")
  else if (p.content != null) trim(p.content as String default "")
  else if (p.body != null) trim(p.body as String default "")
  else trim("" default "")
fun textFromParts(ps) =
  (((ps default []) map ((p) -> partText(p))) filter ((t) -> not isEmpty(trim(t as String default "")))) joinBy "\n"
/** Normalize artifact.parts whether the broker sends an array or a single part object. */
fun partsArray(p) =
  if (p == null) []
  else if (p is Array) p as Array
  else [p]
/** Artifact list → all part objects in order (flatMap avoids edge cases with flatten + map). */
fun textFromArtifacts(arts) =
  textFromParts((arts as Array default []) flatMap ((a) -> partsArray(a.parts)))
/** A2A task often returns the prompt/question on result.message while status = input-required. */
fun textFromResultMessage(m) = do {
  var msg = m default {}
  var direct = trim((msg.text as String) default "")
  var inner = msg.parts
  ---
  if (not isEmpty(direct)) direct
  else if (inner != null and sizeOf(inner as Array) > 0) textFromParts(inner)
  else ""
}
fun lastHistoryText(hist) = if (sizeOf(hist default []) < 1) ""
  else do {
    var last = (hist as Array)[-1] default {}
  ---
    if (last.message != null) textFromResultMessage(last.message)
    else if (last.parts != null) textFromParts(last.parts)
    else trim((last.text as String) default "")
  }
/** Often input-required puts the form/question in an earlier history entry, not the last. */
fun allHistoryText(hist) = if (sizeOf(hist default []) < 1) ""
  else do {
    var arr = (hist as Array) map ((h) -> do {
    var h0 = h default {}
  ---
    if (h0.message != null) textFromResultMessage(h0.message)
    else if (h0.parts != null) textFromParts(h0.parts)
    else trim((h0.text as String) default "")
  })
  var filtered = arr filter ((row) -> not isEmpty(trim(row as String default "")))
  ---
  filtered joinBy "\n"
  }
/** Some brokers nest user-facing text under result.status. */
fun textFromStatusObject(st0) = do {
  var st1 = (st0 default {}) as Object
  var smsg = (st1).message
  var sparts = (st1).parts
  var stext = trim((st1).text as String default "")
  ---
  if (smsg != null) textFromResultMessage(smsg)
  else if (sparts != null and sizeOf(sparts as Array) > 0) textFromParts(sparts)
  else if (not isEmpty(stext)) stext
  else ""
}
var r = payload
---
if (r.error != null)
  do {
    var emsg = trim((r.error.message default "") as String)
    var ecode = r.error.code default null
    var rawErr = (write(r.error)) as String
    var clipRaw = if (sizeOf(rawErr) > 1200) substring(rawErr, 0, 1200) ++ "…" else rawErr
  ---
    {
      reply: "There was an issue processing the response. Please try again in a moment.",
      error: true,
      debug: {
        errorType: "JSON-RPC",
        code: ecode,
        detail: if (isEmpty(emsg)) clipRaw else emsg
      }
    }
  }
else if (r.result != null)
  do {
    var res = r.result
    var st = (res.status default {}).state as String default ""
    var fromParts = if (sizeOf(res.parts default []) > 0) textFromParts(res.parts) else ""
    var fromArtifacts = if (sizeOf(res.artifacts default []) > 0) textFromArtifacts(res.artifacts) else ""
    var fromMessage = if (res.message != null) textFromResultMessage(res.message) else ""
    var fromStat = if (res.status != null) textFromStatusObject(res.status) else ""
    var fromHistoryAll = if (sizeOf(res.history default []) > 0) allHistoryText(res.history) else ""
    var fromHistory = if (sizeOf(res.history default []) > 0) lastHistoryText(res.history) else ""
    var fromTask = if (res.task == null) ""
        else if (res.task is String) trim(res.task as String)
        else textFromResultMessage(res.task)
    var body = if (not isEmpty(trim(fromParts))) fromParts
        else if (not isEmpty(trim(fromArtifacts))) fromArtifacts
        else if (not isEmpty(trim(fromMessage))) fromMessage
        else if (not isEmpty(trim(fromStat))) fromStat
        else if (not isEmpty(trim(fromHistoryAll))) fromHistoryAll
        else if (not isEmpty(trim(fromHistory))) fromHistory
        else if (not isEmpty(trim(fromTask))) fromTask
        else ""
  ---
  if (not isEmpty(trim(body)))
    { reply: body }
  else if (st == "input-required")
    { reply: "The agent needs more information to continue. Send a follow-up with the details it asked for." }
  else if (not isEmpty(trim(st)))
    { reply: "The agent returned status \"" ++ st ++ "\". If the run is not done, try sending one more follow-up message." }
  else
    { reply: write(res, "application/json") }
  }
else
  { reply: write(r, "application/json") }

